{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-pBamUh/src/address.js","content":"/**
 * Cell addresses: one or two letters naming a column (A..Z, AA..ZZ) and one
 * to three digits naming a row of at least 1. Columns are ordered with a
 * bijective base-26 index so "A" < "Z" < "AA" < "ZZ".
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Bijective base-26 index for a column's letters (A=1, Z=26, AA=27, ZZ=702). */
function colIndex(letters) {
  let n = 0
  for (const ch of letters.toUpperCase()) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

/**
 * Parses a raw token as a cell address. Returns null when the token is not
 * shaped like an address or names a row below 1, which covers every case
 * the spec calls "outside the addressable range".
 */
export function parseAddress(token) {
  const m = ADDRESS_RE.exec(token)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  const col = colIndex(letters)
  return { col, row, key: `${letters}${row}` }
}

/** Orders addresses by ascending column, then ascending row. */
export function compareAddresses(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}
"}

