{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-pBamUh/src/values.js","content":"/**
 * Sheet values: numbers, text, booleans, and errors. Each is a plain
 * `{ t, v }` tag so evaluation code can branch on `t` without classes.
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export const num = (v) => ({ t: 'num', v })
export const text = (v) => ({ t: 'text', v })
export const bool = (v) => ({ t: 'bool', v })
export const err = (v) => ({ t: 'err', v })

export const isErr = (value) => value.t === 'err'

/** Converts a value to a number for arithmetic, per the coercion rules. */
export function toNumber(value) {
  if (value.t === 'num') return value
  if (value.t === 'bool') return num(value.v ? 1 : 0)
  if (value.t === 'err') return value
  return err('#VALUE!')
}

/** Arithmetic results that are not finite (including division by zero) are #DIV/0!. */
export function checkFinite(n) {
  return Number.isFinite(n) ? num(n) : err('#DIV/0!')
}

const KIND_RANK = { num: 0, text: 1, bool: 2 }

/**
 * Compares two non-error values per the spec's total order: numbers below
 * text below booleans, with each kind compared naturally within itself.
 */
export function compareValues(a, b) {
  const ra = KIND_RANK[a.t]
  const rb = KIND_RANK[b.t]
  if (ra !== rb) return ra - rb
  if (a.t === 'num') return a.v - b.v
  if (a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  // booleans: false below true
  if (a.v === b.v) return 0
  return a.v ? 1 : -1
}

/** Rounds a finite number to ten significant digits, then formats it as JS would. */
export function formatNumber(n) {
  if (!Number.isFinite(n) || n === 0) return String(n === 0 ? 0 : n)
  const magnitude = Math.floor(Math.log10(Math.abs(n))) + 1
  const factor = Math.pow(10, 10 - magnitude)
  let rounded = Math.round(n * factor) / factor
  if (rounded === 0) rounded = 0
  return String(rounded)
}

export function formatValue(value) {
  switch (value.t) {
    case 'num':
      return formatNumber(value.v)
    case 'bool':
      return value.v ? 'TRUE' : 'FALSE'
    case 'err':
      return value.v
    case 'text':
      return value.v
    default:
      throw new Error(`unknown value kind: ${value.t}`)
  }
}
"}

