 * Tokenizer for a formula body (the text after the leading `=`). Throws
 * `FormulaError` on any character it cannot match, which the caller turns
 * into `#ERR!` for the cell.
 */

export class FormulaError extends Error {}

const NUMBER_RE = /^[0-9]+(\.[0-9]+)?/
const IDENT_RE = /^[A-Za-z]+[0-9]*/

const PUNCT = [
  ['<=', 'LE'],
  ['>=', 'GE'],
  ['<>', 'NE'],
  ['(', 'LPAREN'],
  [')', 'RPAREN'],
  [',', 'COMMA'],
  [':', 'COLON'],
  ['^', 'CARET'],
  ['*', 'STAR'],
  ['/', 'SLASH'],
  ['+', 'PLUS'],
  ['-', 'MINUS'],
  ['=', 'EQ'],
  ['<', 'LT'],
  ['>', 'GT'],
]

export function tokenize(body) {
  const tokens = []
  let i = 0
  while (i < body.length) {
    const ch = body[i]
    if (ch === ' ' || ch === '\t') {
      i += 1
      continue
    }
    const rest = body.slice(i)
    const numMatch = NUMBER_RE.exec(rest)
    if (numMatch) {
      tokens.push({ type: 'NUMBER', value: numMatch[0] })
      i += numMatch[0].length
      continue
    }
    const identMatch = IDENT_RE.exec(rest)
    if (identMatch) {
      tokens.push({ type: 'IDENT', value: identMatch[0].toUpperCase() })
      i += identMatch[0].length
      continue
    }
    const punct = PUNCT.find(([text]) => rest.startsWith(text))
    if (punct) {
      tokens.push({ type: punct[1], value: punct[0] })
      i += punct[0].length
      continue
    }
    throw new FormulaError(`unexpected character ${ch}`)
  }
  tokens.push({ type: 'EOF', value: '' })
  return tokens
}
"}

