 * Recursive-descent parser for a formula's token stream, producing an AST.
 * Precedence loosest to tightest: comparisons, +/-, * //, ^ (right assoc),
 * then a leading unary sign, which binds tighter than ^.
 *
 * A range (`A1:B2`) parses as a primary anywhere an expression can appear,
 * since `deps` must still name the cells of a range used somewhere other
 * than directly as a function argument; evaluating such a misplaced range
 * as a plain value is what makes the cell `#ERR!`.
 */

import { FormulaError } from './lexer.js'

const COMPARISON_TYPES = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])
const ADDITIVE_TYPES = new Set(['PLUS', 'MINUS'])
const MULTIPLICATIVE_TYPES = new Set(['STAR', 'SLASH'])

const KNOWN_NAMES = new Set(['TRUE', 'FALSE'])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const tok = this.peek()
    if (tok.type !== type) throw new FormulaError(`expected ${type}, got ${tok.type}`)
    return this.next()
  }

  parseFormula() {
    const expr = this.parseComparison()
    this.expect('EOF')
    return expr
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (COMPARISON_TYPES.has(this.peek().type)) {
      const op = this.next()
      const right = this.parseAdditive()
      left = { type: 'BinOp', op: op.type, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (ADDITIVE_TYPES.has(this.peek().type)) {
      const op = this.next()
      const right = this.parseMultiplicative()
      left = { type: 'BinOp', op: op.type, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (MULTIPLICATIVE_TYPES.has(this.peek().type)) {
      const op = this.next()
      const right = this.parsePower()
      left = { type: 'BinOp', op: op.type, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.peek().type === 'CARET') {
      this.next()
      const right = this.parsePower()
      return { type: 'BinOp', op: 'CARET', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.peek().type === 'PLUS' || this.peek().type === 'MINUS') {
      const op = this.next()
      const expr = this.parseUnary()
      return { type: 'Unary', op: op.type, expr }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const tok = this.peek()
    if (tok.type === 'NUMBER') {
      this.next()
      return { type: 'Number', value: parseFloat(tok.value) }
    }
    if (tok.type === 'LPAREN') {
      this.next()
      const expr = this.parseComparison()
      this.expect('RPAREN')
      return expr
    }
    if (tok.type === 'IDENT') {
      // A range is a primary in its own right, wherever one appears.
      if (this.peek(1).type === 'COLON' && this.peek(2).type === 'IDENT') {
        const from = this.next().value
        this.next() // COLON
        const to = this.next().value
        return { type: 'Range', from, to }
      }
      this.next()
      if (tok.value === 'TRUE' || tok.value === 'FALSE') {
        return { type: 'Bool', value: tok.value === 'TRUE' }
      }
      if (this.peek().type === 'LPAREN') {
