import { tokenize, FormulaError } from './lexer.js'
import { parseFormula } from './parser.js'
import { num, text, err, ERROR_TOKENS } from './values.js'

const NUMBER_LITERAL_RE = /^-?[0-9]+(\.[0-9]+)?$/

