 * Reads a sheet from raw input text into a map of declared cells, keyed by
 * canonical address. Throws `SheetError` on the first malformed line.
 */

import { parseAddress, compareAddresses } from './address.js'

export class SheetError extends Error {}

const ADDRESS_TOKEN_RE = /^[A-Za-z]{1,2}[0-9]{1,3}$/

/** Splits input on newlines, dropping the empty tail a trailing newline leaves. */
function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/** Parses one already-left-stripped, non-comment line into `{ token, content }`. */
function splitAddressAndContent(stripped) {
  const sepIndex = stripped.search(/[ \t]/)
  if (sepIndex === -1) return { token: stripped, content: '' }
  const token = stripped.slice(0, sepIndex)
  const rest = stripped.slice(sepIndex)
  const sepMatch = /^[ \t]+/.exec(rest)
  const content = rest.slice(sepMatch[0].length)
  return { token, content }
}

/** Parses the sheet, returning declared cells sorted by column then row. */
export function parseSheet(input) {
  const lines = splitLines(input)
  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const stripped = lines[i].replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    const { token, content } = splitAddressAndContent(stripped)
    if (!ADDRESS_TOKEN_RE.test(token) || parseAddress(token) === null) {
      throw new SheetError(`line ${lineNumber}: invalid cell address ${token}`)
    }
    const address = parseAddress(token)
    if (cells.has(address.key)) {
      throw new SheetError(`line ${lineNumber}: cell ${address.key} is declared twice`)
    }
    cells.set(address.key, { address, content })
  }

  const ordered = [...cells.values()].sort((a, b) => compareAddresses(a.address, b.address))
  return { cells, ordered }
}
"}

