  if (name === 'IF') return evalIf(node, ctx)
  if (name === 'ABS') return evalAbs(node, ctx)
  if (AGGREGATE_FUNCTIONS.has(name)) return evalAggregate(name, node, ctx)
  return err('#NAME?')
