  const e = firstError(items)
  if (e) return e

  if (name === 'COUNT') {
    return num(items.filter((v) => v.t === 'num').length)
  }

  const nums = []
  for (const item of items) {
    const n = toNumber(item)
    if (isErr(n)) return n
    nums.push(n.v)
  }

  if (name === 'SUM') return checkFinite(nums.reduce((a, b) => a + b, 0))
  if (name === 'AVG') return checkFinite(nums.reduce((a, b) => a + b, 0) / nums.length)
  if (name === 'MIN') return num(Math.min(...nums))
  if (name === 'MAX') return num(Math.max(...nums))
  throw new Error(`unknown aggregate: ${name}`)
}

/** Collects every distinct in-range address a formula AST names directly, ordered. */
export function collectDeps(ast) {
  const found = new Map()
  function visitAddress(text) {
    const addr = parseAddress(text)
    if (addr) found.set(addr.key, addr)
  }
  function visit(node) {
    switch (node.type) {
      case 'Number':
      case 'Bool':
        return
      case 'Address':
        visitAddress(node.text)
        return
      case 'Range': {
        const keys = expandRange(node)
        if (keys) for (const key of keys) visitAddress(key)
        return
      }
      case 'Unary':
        visit(node.expr)
        return
      case 'BinOp':
        visit(node.left)
        visit(node.right)
        return
      case 'Call':
        for (const arg of node.args) visit(arg)
        return
      default:
        throw new Error(`unknown node type: ${node.type}`)
    }
  }
  if (ast) visit(ast)
  return [...found.values()].sort(compareAddresses)
}
