/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { EvalContext, collectDeps } from './evaluator.js'
import { formatValue } from './values.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('usage: cli.js values|deps')
  }

  const input = readFileSync(0, 'utf8')

  let sheet
  try {
    sheet = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
  }

  const out = []
  if (mode === 'values') {
    const ctx = new EvalContext(sheet)
    for (const cell of sheet.ordered) {
      const value = ctx.evalAddress(cell.address.key)
      out.push(`${cell.address.key}=${formatValue(value)}\n`)
    }
  } else {
    for (const cell of sheet.ordered) {
      const parsed = cell.content.startsWith('=')
        ? tryParseFormula(cell.content)
        : null
      const deps = parsed ? collectDeps(parsed) : []
      const suffix = deps.map((addr) => ` ${addr.key}`).join('')
      out.push(`${cell.address.key}:${suffix}\n`)
    }
  }
  process.stdout.write(out.join(''))
}

function tryParseFormula(content) {
  const { parseContent } = importParseContentSync()
  return parseContent(content).ast
}

main()
"}

